begin;
create schema test;
grant usage on schema test to authenticated,anon;
create function test.ok(condition boolean,label text) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function test.denied(statement text,fragment text) returns void language plpgsql as $$ begin
 begin execute statement; exception when others then
  if position(fragment in sqlerrm)>0 then raise notice 'PASS: rejected %',fragment; return; end if;
  raise exception 'Unexpected error: % (expected %)',sqlerrm,fragment;
 end;
 raise exception 'FAIL: mutation should have been rejected: %',statement;
end $$;
grant execute on all functions in schema test to authenticated,anon;
insert into auth.users(id,email) values
 ('10000000-0000-0000-0000-000000000001','admin@test.invalid'),
 ('10000000-0000-0000-0000-000000000002','editor@test.invalid'),
 ('10000000-0000-0000-0000-000000000003','reader@test.invalid'),
 ('10000000-0000-0000-0000-000000000004','outsider@test.invalid');
update volunteers set active=true,full_name='Test Admin',role='admin' where id='10000000-0000-0000-0000-000000000001';
update volunteers set active=true,full_name='Test Editor',role='editor' where id='10000000-0000-0000-0000-000000000002';
update volunteers set active=true,full_name='Test Reader' where id='10000000-0000-0000-0000-000000000003';
select test.ok(not (select active from volunteers where email='outsider@test.invalid'),'uninvited Auth accounts have no active membership');
insert into invitation_allowlist(email,full_name,invited_by) values('invited@test.invalid','Invited Person','10000000-0000-0000-0000-000000000001');
insert into auth.users(id,email) values('10000000-0000-0000-0000-000000000005','invited@test.invalid');
select test.ok((select active and role='viewer' and full_name='Invited Person' from volunteers where email='invited@test.invalid'),'invites always begin as viewer');

set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select save_record('animal','{"id":"20000000-0000-0000-0000-000000000001","name":"Lua","species":"dog","sex":"female","admitted_on":"2020-01-01","home_base_id":"00000000-0000-0000-0000-000000000001","status":"available","neutered":"unknown","rabies_vaccinated":"unknown","leishmaniasis":"unknown"}');
select save_record('animal','{"id":"20000000-0000-0000-0000-000000000002","name":"Sol","species":"cat","sex":"male","admitted_on":"2020-01-01","home_base_id":"00000000-0000-0000-0000-000000000002","status":"available","neutered":"yes","rabies_vaccinated":"no","leishmaniasis":"unknown"}');
select save_record('animal','{"id":"20000000-0000-0000-0000-000000000003","name":"Estrela","species":"cat","sex":"female","admitted_on":"2020-01-01","home_base_id":"00000000-0000-0000-0000-000000000001","status":"available","neutered":"yes","rabies_vaccinated":"yes","leishmaniasis":"no"}');
select save_record('adopter','{"id":"30000000-0000-0000-0000-000000000001","full_name":"Adotante Um","birth_date":"1990-01-01","cpf":"11144477735","phone":"85999999999","email":"adopter1@test.invalid","street":"Rua Um","number":"1","neighborhood":"Centro","city":"Fortaleza","state":"CE","postal_code":"60000000","has_other_animals":false}');
select save_record('adopter','{"id":"30000000-0000-0000-0000-000000000002","full_name":"Adotante Dois","birth_date":"1990-01-01","cpf":"52998224725","phone":"85999999999","email":"adopter2@test.invalid","street":"Rua Dois","number":"2","neighborhood":"Centro","city":"Fortaleza","state":"CE","postal_code":"60000000","has_other_animals":false}');
select create_adoption(jsonb_build_object('animal_ids',array['20000000-0000-0000-0000-000000000001'],'adopter_id','30000000-0000-0000-0000-000000000001','adopted_on',current_date-10));
select set_config('test.dog_adoption',(select id::text from adoptions where animal_id='20000000-0000-0000-0000-000000000001'),true);
select test.denied($q$ select create_adoption(jsonb_build_object('animal_ids',array['20000000-0000-0000-0000-000000000001'],'adopter_id','30000000-0000-0000-0000-000000000002','adopted_on',current_date)) $q$,'não está disponível');
select test.denied($q$ select close_followup(current_setting('test.dog_adoption')::uuid,'adopted') $q$,'encerramento deve ser');
select set_config('test.visit1',schedule_visit(jsonb_build_object('adoption_ids',array[current_setting('test.dog_adoption')],'visitor_id','10000000-0000-0000-0000-000000000002','scheduled_at',now()-interval '3 days'))::text,true);
select record_visit(jsonb_build_object('id',current_setting('test.visit1'),'visited_at',now()-interval '3 days','results',jsonb_build_array(jsonb_build_object('adoption_id',current_setting('test.dog_adoption'),'outcome','well_cared'))));
select test.denied($q$ select close_followup(current_setting('test.dog_adoption')::uuid,'adopted') $q$,'três visitas');
select set_config('test.visit2',schedule_visit(jsonb_build_object('adoption_ids',array[current_setting('test.dog_adoption')],'visitor_id','10000000-0000-0000-0000-000000000002','scheduled_at',now()-interval '2 days'))::text,true);
select record_visit(jsonb_build_object('id',current_setting('test.visit2'),'visited_at',now()-interval '2 days','results',jsonb_build_array(jsonb_build_object('adoption_id',current_setting('test.dog_adoption'),'outcome','needs_attention'))));
select create_adoption(jsonb_build_object('animal_ids',array['20000000-0000-0000-0000-000000000002'],'adopter_id','30000000-0000-0000-0000-000000000001','adopted_on',current_date-1));
select set_config('test.cat_adoption',(select id::text from adoptions where animal_id='20000000-0000-0000-0000-000000000002'),true);
select set_config('test.visit3',schedule_visit(jsonb_build_object('adoption_ids',array[current_setting('test.dog_adoption'),current_setting('test.cat_adoption')],'visitor_id','10000000-0000-0000-0000-000000000002','scheduled_at',now()))::text,true);
select test.denied($q$ select record_visit(jsonb_build_object('id',current_setting('test.visit3'),'results',jsonb_build_array(jsonb_build_object('adoption_id',current_setting('test.dog_adoption'),'outcome','well_cared')))) $q$,'resultado para cada animal');
select record_visit(jsonb_build_object('id',current_setting('test.visit3'),'results',jsonb_build_array(jsonb_build_object('adoption_id',current_setting('test.dog_adoption'),'outcome','needs_attention'),jsonb_build_object('adoption_id',current_setting('test.cat_adoption'),'outcome','well_cared'))));
select test.ok((select count(*) from visit_animals va join visits v on v.id=va.visit_id where adoption_id=current_setting('test.dog_adoption')::uuid and visited_at is not null)=3,'dog reaches three visits');
select test.ok((select count(*) from visit_animals va join visits v on v.id=va.visit_id where adoption_id=current_setting('test.cat_adoption')::uuid and visited_at is not null)=1,'later cat adoption has one independent visit');
select test.denied($q$ select schedule_visit(jsonb_build_object('adoption_ids',array[current_setting('test.dog_adoption')],'visitor_id','10000000-0000-0000-0000-000000000002','scheduled_at',now())) $q$,'três visitas');
select close_followup(current_setting('test.dog_adoption')::uuid,'adopted');
select test.ok((select status from animals where id='20000000-0000-0000-0000-000000000001')='adopted','closing follow-up preserves current placement');
select test.denied($q$ select create_adoption(jsonb_build_object('animal_ids',array['20000000-0000-0000-0000-000000000001'],'adopter_id','30000000-0000-0000-0000-000000000002','adopted_on',current_date)) $q$,'não está disponível');
select close_followup(current_setting('test.cat_adoption')::uuid,'recollected','Retorno físico confirmado pelo visitante.');
select test.ok((select status='assessment' and home_base_id='00000000-0000-0000-0000-000000000002' from animals where id='20000000-0000-0000-0000-000000000002'),'early return restores origin base and requires assessment');
select test.denied($q$ select create_adoption(jsonb_build_object('animal_ids',array['20000000-0000-0000-0000-000000000002'],'adopter_id','30000000-0000-0000-0000-000000000002','adopted_on',current_date)) $q$,'não está disponível');
select save_record('animal',(select to_jsonb(a)||'{"status":"available"}'::jsonb from animals a where id='20000000-0000-0000-0000-000000000002'));
select create_adoption(jsonb_build_object('animal_ids',array['20000000-0000-0000-0000-000000000002'],'adopter_id','30000000-0000-0000-0000-000000000002','adopted_on',current_date));
select test.ok((select count(*) from adoptions where animal_id='20000000-0000-0000-0000-000000000002')=2,'new adoption preserves returned placement');
select test.denied($q$ select schedule_visit(jsonb_build_object('adoption_ids',(select array_agg(id::text) from adoptions where ended_at is null),'visitor_id','10000000-0000-0000-0000-000000000002','scheduled_at',now())) $q$,'Acompanhamento encerrado');
select save_record('treatment',jsonb_build_object('id','40000000-0000-0000-0000-000000000001','animal_id','20000000-0000-0000-0000-000000000001','name','Tratamento diário','instructions','Conforme orientação recebida','start_date',current_date-2,'total_doses',3,'schedule_type','daily','time_of_day','09:00','timezone','America/Fortaleza'));
select test.ok((select count(*) from treatment_doses where treatment_id='40000000-0000-0000-0000-000000000001')=3,'count-based daily treatment creates exactly three applications');
select save_record('treatment',jsonb_build_object('id','40000000-0000-0000-0000-000000000002','animal_id','20000000-0000-0000-0000-000000000001','name','Tratamento semanal','start_date',current_date,'total_doses',6,'schedule_type','weekly','weekdays',array[1,3,5],'time_of_day','09:00','timezone','America/Fortaleza'));
select test.ok((select count(*)=6 and bool_and(extract(isodow from scheduled_at at time zone 'America/Fortaleza') in (1,3,5)) from treatment_doses where treatment_id='40000000-0000-0000-0000-000000000002'),'weekly schedule respects weekdays and count');
select save_record('treatment',jsonb_build_object('id','40000000-0000-0000-0000-000000000003','animal_id','20000000-0000-0000-0000-000000000001','name','Tratamento por horas','start_date',current_date,'total_doses',4,'schedule_type','hourly','interval_hours',8,'time_of_day','09:00','timezone','America/Fortaleza'));
select test.ok((select count(*)=4 and max(scheduled_at)-min(scheduled_at)=interval '24 hours' from treatment_doses where treatment_id='40000000-0000-0000-0000-000000000003'),'hourly schedule respects interval');
select set_config('test.original_dates',(select jsonb_agg(scheduled_at order by scheduled_at)::text from treatment_doses where treatment_id='40000000-0000-0000-0000-000000000001'),true);
select record_dose((select id from treatment_doses where treatment_id='40000000-0000-0000-0000-000000000001' order by scheduled_at limit 1),now(),'Aplicação registrada com atraso.');
select test.ok((select jsonb_agg(scheduled_at order by scheduled_at)::text from treatment_doses where treatment_id='40000000-0000-0000-0000-000000000001')=current_setting('test.original_dates'),'late application never moves remaining dates');
select save_record('vaccination',jsonb_build_object('animal_id','20000000-0000-0000-0000-000000000001','name','Raiva','administered_on',current_date-365,'next_due_on',current_date));
select save_record('vaccination',jsonb_build_object('animal_id','20000000-0000-0000-0000-000000000001','name','raiva','administered_on',current_date,'next_due_on',current_date+365));
select test.ok((select count(*) from needs_feed where kind='vaccine')=1,'new dose replaces old vaccine reminder but preserves history');
select save_record('vaccination',jsonb_build_object('id','50000000-0000-0000-0000-000000000001','animal_id','20000000-0000-0000-0000-000000000003','name','Vacina planejada','scheduled_on',current_date+2));
select test.ok((select administered_on is null from vaccinations where id='50000000-0000-0000-0000-000000000001'),'scheduled vaccine never fabricates an administration');
select test.ok(exists(select 1 from needs_feed where reference_id='50000000-0000-0000-0000-000000000001' and kind='vaccine'),'first vaccine can appear in feed before any actual dose');
select save_record('vaccination',jsonb_build_object('id','50000000-0000-0000-0000-000000000001','animal_id','20000000-0000-0000-0000-000000000003','name','Vacina planejada','administered_on',current_date,'next_due_on',current_date+365));
select test.ok((select administered_on=current_date and scheduled_on=current_date+2 from vaccinations where id='50000000-0000-0000-0000-000000000001'),'actual vaccine completion preserves its original scheduled date');
select test.denied($q$ select save_record('vaccination',jsonb_build_object('id','50000000-0000-0000-0000-000000000001','animal_id','20000000-0000-0000-0000-000000000003','name','Vacina planejada','administered_on',current_date)) $q$,'já possui uma aplicação');
select test.ok((get_snapshot()->'animals')::jsonb is not null,'snapshot readable by active member');
select test.denied($q$ update volunteers set role='admin' where email='editor@test.invalid' $q$,'permission denied');
select test.denied($q$ delete from animals $q$,'permission denied');
select test.denied($q$ select * from invitation_allowlist $q$,'permission denied');
select test.denied($q$ select archive_record('animal','20000000-0000-0000-0000-000000000003') $q$,'permissão');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select test.ok((select count(*) from animals)=3,'viewer can consult animals');
select test.denied($q$ insert into storage.objects(bucket_id,name) values('animal-photos','20000000-0000-0000-0000-000000000001/60000000-0000-0000-0000-000000000001.jpg') $q$,'row-level security');
select test.denied($q$ select save_record('animal','{}') $q$,'permissão');
select test.denied($q$ select record_dose('00000000-0000-0000-0000-000000000000') $q$,'permissão');
select test.denied($q$ select set_volunteer_role('10000000-0000-0000-0000-000000000003','admin') $q$,'permissão');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
select test.ok((select count(*) from animals)=0,'uninvited user sees no rows');
select test.denied($q$ select get_snapshot() $q$,'pendente');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select test.denied($q$ select set_volunteer_role('10000000-0000-0000-0000-000000000001','viewer') $q$,'um administrador');
select test.denied($q$ select archive_record('volunteer','10000000-0000-0000-0000-000000000001') $q$,'um administrador');
select archive_record('animal','20000000-0000-0000-0000-000000000003');
select test.ok((select archived_at is not null from animals where id='20000000-0000-0000-0000-000000000003'),'admin can archive unused animal');
select restore_record('animal','20000000-0000-0000-0000-000000000003');
select test.ok((select archived_at is null from animals where id='20000000-0000-0000-0000-000000000003'),'admin can restore archived records');
select test.denied($q$ select archive_record('animal','20000000-0000-0000-0000-000000000001',true) $q$,'adoção vigente');
select archive_record('volunteer','10000000-0000-0000-0000-000000000003');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select test.ok((select count(*) from animals)=0,'deactivation immediately revokes data access even with existing token');
reset role;
set local role anon;
select test.denied($q$ select get_snapshot() $q$,'permission denied');
reset role;
rollback;
